//! 🔬️ One genuine finite caller preserves physical custody, direct work and complete refusals.
use semio_framework_job::{close_original_granted_step,close_original_nested_step,close_original_retained_step,InteractiveJobCloseStep,OriginalJobFixtureCaller,RetainedCloneGrant,RetainedCloneProgress,Generation,OperationId,StepBudget};
use semio_framework_value::{RetainedWorkOutcome,ValueError,ValueRefusalKind,retirement::controlled::ControlledRetirement};
#[global_allocator]
static ORIGINAL_CLOSE_HEAP:semio_framework_trace::HeapWitness=semio_framework_trace::HeapWitness;
fn clock()->Option<u64>{Some(1)}
fn bank()->RetainedCloneGrant{let row:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let s=&row["originalLifetime"];RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize}}
fn caller()->OriginalJobFixtureCaller{OriginalJobFixtureCaller::admit(OperationId(71),Generation(3),bank(),clock,12345,100000)}
fn delta(a:RetainedCloneProgress,b:RetainedCloneProgress)->RetainedCloneProgress{RetainedCloneProgress{copied_items:a.copied_items-b.copied_items,copied_bytes:a.copied_bytes-b.copied_bytes,retained_capacity_bytes:a.retained_capacity_bytes-b.retained_capacity_bytes,released_bytes:a.released_bytes-b.released_bytes}}
#[test]
fn original_close_context_denied_work_and_deadline_preserve_owned_source(){
 let source=vec![7u8;1799];let pointer=source.as_ptr();let mut owner=ControlledRetirement::retain(source);let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:64,maximum_capacity_bytes:262144,maximum_release_bytes:262144,maximum_depth:128};let mut caller=caller();
 for budget in [StepBudget::new(0,12345,grant),StepBudget::new(1,0,grant)]{caller.turn(grant,|cx|{let before=cx.retained_progress();cx.with_original_work_loan(budget.fuel,budget.deadline_us,|cx|{let demand=owner.selected_demand(cx.retained_grant().maximum_copy_bytes)?;let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||close_original_retained_step(cx,demand,|g|{let result=owner.step(g);RetainedWorkOutcome{result,work:owner.last_turn_work()}}));assert_eq!(result?.progress(),Default::default());assert_eq!(cx.retained_progress(),before);assert_eq!(owner.original().unwrap().as_ptr(),pointer);assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));Ok(())})}).unwrap();}
 let mut freed=0;let mut born=0;caller.cancel().cancel_now();
 for turn in 0..100000{if owner.terminal_is_empty(){break}caller.turn(grant,|cx|{cx.with_original_work_loan(1,12345,|cx|{assert!(cx.is_cancelled());let before=cx.retained_progress();let demand=owner.selected_demand(cx.retained_grant().maximum_copy_bytes)?;let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||close_original_retained_step(cx,demand,|g|{let result=owner.step(g);RetainedWorkOutcome{result,work:owner.last_turn_work()}}));let step=result?;let actual=delta(cx.retained_progress(),before);assert_eq!(step.progress(),actual);assert!(actual.fits(grant));assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(actual.retained_capacity_bytes,actual.released_bytes));assert!(cx.original_work_units_spent()<=1);born+=heap.requested_bytes;freed+=heap.released_bytes;Ok(())})}).unwrap();assert!(turn<99999,"same original source close did not complete");}assert!(owner.terminal_is_empty());assert_eq!(1799+born,freed);let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(owner));assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));caller.retire(bank());
}
#[test]
fn granted_close_body_is_debited_once_and_its_refusal_keeps_the_whole_error(){
 let grant=RetainedCloneGrant{maximum_items:4,maximum_copy_bytes:64,maximum_capacity_bytes:262144,maximum_release_bytes:262144,maximum_depth:128};let mut caller=caller();let mut buffer=Some(vec![0u8;8]);
 caller.turn(grant,|cx|{cx.with_original_work_loan(3,12345,|cx|{
  let before=cx.retained_progress();let progress=RetainedCloneProgress{copied_items:1,released_bytes:8,..Default::default()};let mut seen=0;let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||close_original_granted_step(cx,|granted|{seen=granted.maximum_items;drop(buffer.take());RetainedWorkOutcome::<_,ValueError>{result:Ok(InteractiveJobCloseStep::Pending{progress}),work:1}}));let step=step?;assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,8));assert_eq!((step,seen,delta(cx.retained_progress(),before),cx.fuel_remaining()),(InteractiveJobCloseStep::Pending{progress},4,progress,2));
  let refused=RetainedCloneProgress{copied_items:1,..Default::default()};let error=ValueError::literal(ValueRefusalKind::InvariantViolated,"granted close refused").with_retained_progress(refused);let mut refused_seen=false;
  let failure=close_original_granted_step(cx,|granted|{seen=granted.maximum_items;refused_seen=true;RetainedWorkOutcome{result:Err(error),work:1}}).unwrap_err();assert!(refused_seen);assert_eq!((seen,failure.primary_value().map(|error|error.kind),failure.receipt_refusal.is_none(),cx.fuel_remaining()),(3,Some(ValueRefusalKind::InvariantViolated),true,1));assert_eq!(delta(cx.retained_progress(),before).copied_items,2);
  let blocked=close_original_granted_step(cx,|g|{assert!(g.maximum_depth>0);RetainedWorkOutcome::<_,ValueError>{result:Ok(InteractiveJobCloseStep::Blocked),work:1}})?;assert_eq!((blocked,cx.fuel_remaining()),(InteractiveJobCloseStep::Blocked,0));let mut ran=false;let yielded=close_original_granted_step(cx,|_|{ran=true;RetainedWorkOutcome::<_,ValueError>{result:Ok(InteractiveJobCloseStep::Blocked),work:0}})?;assert_eq!((yielded,ran,delta(cx.retained_progress(),before).copied_items),(InteractiveJobCloseStep::Pending{progress:Default::default()},false,2));Ok(())
 })}).unwrap();caller.retire(bank());
}
#[test]
fn nested_close_body_debits_only_the_remainder_its_nested_callers_did_not_post(){
 let grant=RetainedCloneGrant{maximum_items:4,maximum_copy_bytes:64,maximum_capacity_bytes:262144,maximum_release_bytes:262144,maximum_depth:128};let mut caller=caller();let mut buffers=Some((vec![0u8;8],vec![0u8;8]));
 caller.turn(grant,|cx|{cx.with_original_work_loan(3,12345,|cx|{let before=cx.retained_progress();let reported=RetainedCloneProgress{copied_items:2,released_bytes:16,..Default::default()};let posted=RetainedCloneProgress{copied_items:1,..Default::default()};let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||close_original_nested_step(cx,|nested,_|{nested.consume_retained(posted)?;drop(buffers.take());nested.consume_fuel(1);Ok(InteractiveJobCloseStep::Pending{progress:reported})}));assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,16));assert_eq!((step?,delta(cx.retained_progress(),before),cx.fuel_remaining()),(InteractiveJobCloseStep::Pending{progress:reported},reported,2));let failure=close_original_nested_step(cx,|nested,_|{nested.consume_retained(posted)?;nested.consume_fuel(1);Ok(InteractiveJobCloseStep::Pending{progress:Default::default()})}).unwrap_err();assert_eq!(failure.primary_value().map(|error|error.kind),Some(ValueRefusalKind::InvariantViolated));Ok(())})}).unwrap();caller.retire(bank());
}
#[test]
fn genuine_close_context_lends_exactly_its_grant_and_returns_the_body_outcome(){
 let grant=RetainedCloneGrant{maximum_items:2,maximum_copy_bytes:3,maximum_capacity_bytes:5,maximum_release_bytes:7,maximum_depth:11};let mut caller=caller();
 let value=caller.turn(grant,|cx|{let lent=cx.retained_grant();assert_eq!((lent.maximum_items,lent.maximum_copy_bytes,lent.maximum_capacity_bytes,lent.maximum_release_bytes,lent.maximum_depth),(2,3,5,7,11));assert!(!cx.should_yield());Ok(41+1)}).unwrap();assert_eq!(value,42);
 let(first,second)=(caller.turn(grant,|cx|Ok(cx.retained_grant().maximum_depth)).unwrap(),caller.turn(grant,|cx|Ok(cx.retained_grant().maximum_depth)).unwrap());assert_eq!((first,second),(11,11));let failure=caller.turn(grant,|_|Err::<(),_>(ValueError::literal(ValueRefusalKind::InvariantViolated,"original body refused").into())).unwrap_err();assert_eq!(failure.primary_value().map(|error|error.kind),Some(ValueRefusalKind::InvariantViolated));caller.retire(bank());
}
